const $=id=>document.getElementById(id),canvas=document.querySelector('canvas'),stage=$('stage');
const renderer=new T.WebGLRenderer({canvas,antialias:true});renderer.setPixelRatio(Math.min(devicePixelRatio,2));renderer.shadowMap.enabled=true;renderer.shadowMap.type=T.PCFSoftShadowMap;renderer.outputColorSpace=T.SRGBColorSpace;
const scene=new T.Scene();scene.background=new T.Color('#18262a');scene.fog=new T.Fog('#18262a',16,40);
const camera=new T.PerspectiveCamera(38,1,.02,100),orbit=new OrbitControls(camera,canvas);orbit.enableDamping=false;orbit.minDistance=1.2;orbit.maxDistance=35;orbit.maxPolarAngle=Math.PI*.49;orbit.mouseButtons={LEFT:T.MOUSE.ROTATE,MIDDLE:T.MOUSE.ROTATE,RIGHT:T.MOUSE.PAN};orbit.touches={ONE:T.TOUCH.ROTATE,TWO:T.TOUCH.DOLLY_PAN};
canvas.addEventListener('wheel',e=>{e.preventDefault();e.stopImmediatePropagation();sandboxWheel(T,camera,orbit,e);},{capture:true,passive:false});canvas.addEventListener('pointerdown',e=>{orbit.mouseButtons.LEFT=e.shiftKey?T.MOUSE.PAN:T.MOUSE.ROTATE;},{capture:true});canvas.addEventListener('contextmenu',e=>e.preventDefault());
function fit(){camera.position.set(3.3,2.15,4.7);orbit.target.set(0,.9,0);orbit.update();}$('fit').onclick=fit;fit();new ResizeObserver(()=>{const r=stage.getBoundingClientRect();renderer.setSize(r.width,r.height,false);camera.aspect=r.width/r.height;camera.updateProjectionMatrix();}).observe(stage);
scene.add(new T.HemisphereLight('#dceafa','#59635b',2));const key=new T.DirectionalLight('#fff0d3',3);key.position.set(3,6,4);key.castShadow=true;key.shadow.mapSize.set(2048,2048);key.shadow.camera.left=-5;key.shadow.camera.right=5;key.shadow.camera.top=5;key.shadow.camera.bottom=-5;scene.add(key);const rim=new T.DirectionalLight('#80c5dc',2);rim.position.set(-3,3,-3);scene.add(rim);
const floor=new T.Mesh(new T.PlaneGeometry(60,60),new T.MeshStandardMaterial({color:'#25383b',roughness:.95}));floor.rotation.x=-Math.PI/2;floor.position.y=-.008;floor.receiveShadow=true;scene.add(floor);const grid=new T.GridHelper(12,12,'#58706c','#344b4c');grid.position.y=.001;scene.add(grid);
let mixer,clips=[],active,paused=false,skeleton,sequence=null,seqTime=0;const pretty=s=>s.replaceAll('_',' ').replace(/ Loop$/,'');
function category(n){return /Hit|Death/.test(n)?'Reactions':/Pistol|Punch|Sword|Spell/.test(n)?'Combat':/Walk|Jog|Sprint|Jump|Roll|Crouch|Swim/.test(n)?'Movement':'Everyday';}
function list(){const q=$('search').value.toLowerCase(),cat=$('category').value,shown=clips.filter(c=>pretty(c.name).toLowerCase().includes(q)&&(cat==='All clips'||category(c.name)===cat));$('count').textContent=`${shown.length} / ${clips.length} clips`;$('clips').replaceChildren(...shown.map(c=>{const b=document.createElement('button');b.setAttribute('aria-pressed',String(active?.getClip()===c));const label=document.createElement('span');label.textContent=pretty(c.name);const duration=document.createElement('small');duration.textContent=c.duration.toFixed(2)+'s';b.append(label,duration);b.onclick=()=>{sequence=null;$('sequence').textContent='▶ Play encounter sequence';select(c);};return b;}));}
function select(clip){const next=mixer.clipAction(clip);if(active===next){active.reset().play();}else{next.reset().setEffectiveTimeScale(1).setEffectiveWeight(1).play();if(active){const fade=Number($('blend').value);if(fade)active.crossFadeTo(next,fade,false);else active.stop();}active=next;}active.setLoop(sequence&&!/Loop/.test(clip.name)?T.LoopOnce:$('loop').checked?T.LoopRepeat:T.LoopOnce,Infinity);active.clampWhenFinished=true;paused=false;$('play').textContent='Pause';$('clip-name').textContent=pretty(clip.name);$('clip-meta').textContent=`${category(clip.name)} · ${clip.duration.toFixed(2)} s · Source mannequin`;$('scrub').max=clip.duration;list();}
$('search').oninput=list;$('category').onchange=list;$('play').onclick=()=>{paused=!paused;$('play').textContent=paused?'Play':'Pause';};$('replay').onclick=()=>{if(active){active.reset().play();paused=false;$('play').textContent='Pause';}};$('loop').onchange=()=>{if(active){active.setLoop($('loop').checked?T.LoopRepeat:T.LoopOnce,Infinity);active.clampWhenFinished=true;}};$('skeleton').onchange=()=>skeleton.visible=$('skeleton').checked;
$('scrub').oninput=()=>{if(!active)return;sequence=null;$('sequence').textContent='▶ Play encounter sequence';paused=true;$('play').textContent='Play';mixer.stopAllAction();active.reset().play();active.time=Number($('scrub').value);mixer.update(0);};
$('sequence').onclick=()=>{sequence=['Idle_Loop','Walk_Loop','Sword_Attack','Hit_Chest','Death01'];seqTime=0;select(clips.find(c=>c.name===sequence[0]));$('sequence').textContent='Playing sequence…';};$('help').onclick=()=>$('about').showModal();$('close-help').onclick=()=>$('about').close();
try{const g=await new GLTFLoader().loadAsync('/animation-study-assets/AnimationLibrary_Godot_Standard.gltf');g.scene.traverse(o=>{if(o.isMesh){o.castShadow=true;o.receiveShadow=true;}});scene.add(g.scene);const box=new T.Box3().setFromObject(g.scene),height=box.max.y-box.min.y;g.scene.scale.setScalar(1.8/height);g.scene.position.y=-box.min.y*g.scene.scale.y;mixer=new T.AnimationMixer(g.scene);clips=g.animations;skeleton=new T.SkeletonHelper(g.scene);skeleton.visible=false;scene.add(skeleton);for(const id of ['play','replay','scrub','sequence'])$(id).disabled=false;select(clips.find(c=>c.name==='Idle_Loop'));}catch(e){$('clip-name').textContent='Animation library could not load';$('clip-meta').textContent='Reload to retry';$('count').textContent=e.message;}
let last=performance.now();function frame(now){const dt=Math.min(.05,(now-last)/1000);last=now;if(mixer&&!paused&&!document.hidden){const scaled=dt*Number($('speed').value);mixer.update(scaled);if(sequence){seqTime+=scaled;const duration=/Loop/.test(sequence[0])?2:active.getClip().duration;if(seqTime>=duration){seqTime=0;sequence.shift();if(sequence.length)select(clips.find(c=>c.name===sequence[0]));else{sequence=null;paused=true;$('play').textContent='Play';$('sequence').textContent='▶ Play encounter sequence';}}}}if(active){$('scrub').value=active.time;$('time').textContent=active.time.toFixed(2)+' s';}renderer.render(scene,camera);requestAnimationFrame(frame);}requestAnimationFrame(frame);
